import { ProfilePatch } from './types';

const INVALID = 'invalid profile';
const FIELDS = new Set(['displayName', 'tags']);
const MAX_NAME = 40;
const MAX_TAGS = 5;
const MAX_TAG = 12;

function dataValue(obj: object, key: string): unknown {
  const desc = Object.getOwnPropertyDescriptor(obj, key);
  if (!desc || !('value' in desc)) throw new Error(INVALID); // accessors are rejected
  return desc.value;
}

function parseDisplayName(value: unknown): string | null {
  if (value === null) return null;
  if (typeof value !== 'string') throw new Error(INVALID);
  const trimmed = value.trim();
  if (trimmed.length < 1 || trimmed.length > MAX_NAME) throw new Error(INVALID);
  return trimmed;
}

function parseTags(value: unknown): string[] {
  if (value === null) return [];
  if (!Array.isArray(value)) throw new Error(INVALID);
  if (value.length > MAX_TAGS) throw new Error(INVALID);
  const seen = new Set<string>();
  const out: string[] = [];
  for (let i = 0; i < value.length; i++) {
    if (!Object.prototype.hasOwnProperty.call(value, i)) throw new Error(INVALID); // sparse
    const item = value[i];
    if (typeof item !== 'string') throw new Error(INVALID);
    const trimmed = item.trim();
    if (trimmed.length < 1 || trimmed.length > MAX_TAG) throw new Error(INVALID);
    if (seen.has(trimmed)) throw new Error(INVALID);
    seen.add(trimmed);
    out.push(trimmed); // fresh string array; caller's array is never stored
  }
  return out;
}

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) throw new Error(INVALID);
  const proto = Object.getPrototypeOf(input);
  if (proto !== Object.prototype && proto !== null) throw new Error(INVALID);
  for (const key of Reflect.ownKeys(input)) {
    if (typeof key !== 'string' || !FIELDS.has(key)) throw new Error(INVALID);
  }

  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };
  if (Object.prototype.hasOwnProperty.call(input, 'displayName')) {
    displayName = { kind: 'set', value: parseDisplayName(dataValue(input, 'displayName')) };
  }
  if (Object.prototype.hasOwnProperty.call(input, 'tags')) {
    tags = { kind: 'set', value: parseTags(dataValue(input, 'tags')) };
  }
  return { displayName, tags };
}

